import{_ as t,o as a,c as o,a4 as s}from"./chunks/framework.C83Ss68L.js";const p=JSON.parse('{"title":"Testing","description":"The two test suites that cover the UI kit, what each one can prove, and how to run them.","frontmatter":{"title":"Testing","description":"The two test suites that cover the UI kit, what each one can prove, and how to run them."},"headers":[],"relativePath":"ui-kit/testing.md","filePath":"ui-kit/testing.md","lastUpdated":1792333016000}'),i={name:"ui-kit/testing.md"};function n(r,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>The kit runs two suites against different runtimes, because a component has two halves and neither runtime covers both on its own.</p><table tabindex="0"><thead><tr><th>Suite</th><th>Command</th><th>Runtime</th><th>Proves</th></tr></thead><tbody><tr><td>Unit</td><td><code>bun run check</code></td><td>jsdom</td><td>State, timers, DOM wiring, ARIA attributes, the <code>SSR</code> guards</td></tr><tr><td>Browser</td><td><code>bun run test:e2e</code></td><td>Chromium</td><td>The cascade, real animations, <code>animationend</code> timing, <code>prefers-reduced-motion</code></td></tr><tr><td>Both</td><td><code>bun run test:all</code></td><td></td><td></td></tr></tbody></table><p>Coverage for the kit&#39;s components is measured by <code>bunx vitest run --coverage</code> (see <a href="https://github.com/senseikatana/katanakit-js/blob/dev/CONTRIBUTING.md#test-coverage" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>). It does not gate <code>check</code> or <code>build</code>.</p><p><code>bun run build</code> runs the unit suite as its gate. The browser suite is separate because it needs a browser binary — run it before a release, not on every save.</p><h2 id="why-both-are-needed" tabindex="-1">Why both are needed <a class="header-anchor" href="#why-both-are-needed" aria-label="Permalink to &quot;Why both are needed&quot;">​</a></h2><p>jsdom has no animation engine, so <code>animationend</code> never fires there. The toast&#39;s exit path therefore falls back to its <code>TOAST_EXIT_FALLBACK_MS</code> timer in every unit test, which means <strong>the real exit animation is unreachable from jsdom</strong>.</p><p>That is not hypothetical. The exit path shipped with an unfiltered <code>animationend</code> listener. Because <code>animationend</code> bubbles and the countdown bar animates for exactly the dismiss duration, the bar&#39;s event won the race and removed the toast with no animation at all. All 23 unit tests passed. The bug was invisible until a browser was involved.</p><p><code>tests/e2e/toast.browser.test.ts</code> asserts the exit structurally: it observes the animation events the browser actually delivers and requires <code>katana-toast-out</code> to be among them. Removal driven by the fallback timer cannot produce that event, so the two paths are distinguishable without asserting on wall-clock timings, which would be flaky.</p><h2 id="what-the-browser-suite-covers" tabindex="-1">What the browser suite covers <a class="header-anchor" href="#what-the-browser-suite-covers" aria-label="Permalink to &quot;What the browser suite covers&quot;">​</a></h2><ul><li>Component CSS is applied from the compiled stylesheet, with unprefixed classes.</li><li>Component rules really are inside <code>@layer katana</code>.</li><li>Unlayered rules beat the kit regardless of import order — the guarantee that makes the daisyUI coexistence deterministic.</li><li>The exit animation runs and is what removes the node.</li><li>The progress bar&#39;s own <code>animationend</code> does <strong>not</strong> remove the toast.</li><li>Hover and focus freeze the countdown, and leaving resumes it.</li><li><code>prefers-reduced-motion: reduce</code> removes without waiting for the fallback.</li><li>Live-region roles, the five-toast cap, close-button pruning, and <code>clear()</code> leaving no orphaned nodes.</li></ul><h2 id="fixture" tabindex="-1">Fixture <a class="header-anchor" href="#fixture" aria-label="Permalink to &quot;Fixture&quot;">​</a></h2><p><code>tests/e2e/fixture/index.html</code> is a static page that loads <code>packages/ui/dist/styles.css</code> and <code>dist/index.js</code> and exposes <code>window.toast</code>. <code>scripts/serve-fixture.mjs</code> serves it over http on port <code>4178</code> and rebuilds the UI package first, so the assertions always run against the compiled output rather than the SCSS source.</p><p>It has to be http rather than <code>file://</code>: both <code>@layer</code> resolution and animation timing depend on the browser parsing the real stylesheet.</p><h2 id="browsers" tabindex="-1">Browsers <a class="header-anchor" href="#browsers" aria-label="Permalink to &quot;Browsers&quot;">​</a></h2><p>Playwright resolves Chromium from its local cache. Point it elsewhere with <code>PLAYWRIGHT_CHROMIUM_PATH</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLAYWRIGHT_CHROMIUM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/usr/bin/chromium</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span></span></code></pre></div><h2 id="adding-a-component" tabindex="-1">Adding a component <a class="header-anchor" href="#adding-a-component" aria-label="Permalink to &quot;Adding a component&quot;">​</a></h2><p>A new component should land with both halves:</p><ol><li>A unit suite covering state, timers and ARIA — <code>packages/ui/tests/&lt;name&gt;.test.ts</code>.</li><li>Browser assertions for whatever it does that jsdom structurally cannot: animation, cascade layer, focus order, or anything timing-dependent.</li><li>A docs page carrying the <code>&lt;ComponentContract&gt;</code> block, so the contract stays stated in exactly one place.</li></ol>',20)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
